css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .72); position: relative; }
.loader .bird { position: absolute; inset: 0; animation: crane-glide calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader .body { position: absolute; left: 30%; top: 38%; width: 44%; height: 34%; background: linear-gradient(var(--accent-2), var(--accent)); clip-path: polygon(0 20%, 62% 0, 100% 46%, 46% 100%); }
.loader .wing { position: absolute; top: 12%; width: 38%; height: 44%; background: linear-gradient(color-mix(in srgb, #fff 30%, var(--accent)), var(--accent)); }
.loader .wing:nth-of-type(1) { left: 8%; clip-path: polygon(0 8%, 100% 52%, 62% 100%); transform-origin: 100% 60%; animation: crane-left calc(var(--loader-speed) * .95) ease-in-out infinite; }
.loader .wing:nth-of-type(2) { right: 8%; clip-path: polygon(100% 8%, 0 52%, 38% 100%); transform-origin: 0 60%; animation: crane-right calc(var(--loader-speed) * .95) ease-in-out infinite; }
@keyframes crane-left { 0%, 100% { transform: rotate(-26deg) scaleY(1); } 50% { transform: rotate(22deg) scaleY(.72); } }
@keyframes crane-right { 0%, 100% { transform: rotate(26deg) scaleY(1); } 50% { transform: rotate(-22deg) scaleY(.72); } }
@keyframes crane-glide { 0%, 100% { transform: translateY(4%); } 50% { transform: translateY(-6%); } }
